  input?: PreparedCallInput;
  actor?: Actor;
  /** The run at the top of the call tree. A run nobody called is its own root. */
  root: string;
  parent?: string;
  depth: number;
  mode?: CallMode;
  /** Set on a run another run called. An attached run ends with its caller. A delegated one does not. */
  lifecycle?: "attached" | "delegated";
  /** The schedule that raised the run, if one did. */
  schedule?: string;
  /** The conversation the run belongs to. A run that starts a conversation is its own thread. */
  thread: string;
  /** The turn this one follows. Two runs with the same `prev` are branches. */
